import { describe, it, expect } from 'vitest';
import { processOrder } from '../src/order-processor.js';

describe('discount sanity', () => {
  it('applies discount when discountPercent present', () => {
    const r = processOrder({
      id: 'd1',
      lines: [{ sku: 'a', qty: 2, price: 50 }],
      discountPercent: 10,
    });
    expect(r.subtotal).toBe(100);
    expect(r.total).toBe(90);
    expect(r.discount).toBe(10);
  });

  it('rounds to cents and keeps discount = subtotal - total', () => {
    const r = processOrder({
      id: 'd2',
      lines: [{ sku: 'a', qty: 3, price: 9.99 }],
      discountPercent: 15,
    });
    expect(r.subtotal).toBeCloseTo(29.97, 10);
    expect(r.subtotal - r.total).toBe(r.discount);
  });

  it('discountPercent 0 behaves like no discount', () => {
    const r = processOrder({
      id: 'd3',
      lines: [{ sku: 'a', qty: 1, price: 10 }],
      discountPercent: 0,
    });
    expect(r.total).toBe(10);
    expect(r.discount).toBe(0);
  });
});

